package dev.juukulius.client.fx;

import net.minecraft.util.Mth;
import org.joml.Matrix4f;
import org.joml.Quaternionf;
import org.joml.Vector3f;

/**
 * Where the blade is inside the sword's item model, and the model's display transforms. These values mirror
 * {@code models/item/house_juukulius_sword.json} (generated by {@code tools/gen_models.py}); they let trails and glow
 * effects be computed from the exact matrix the sword is drawn with.
 */
public final class BladeGeometry {
	/** Blade root and tip in model pixels. */
	public static final Vector3f BASE_PX = new Vector3f(8.0F, 8.6F, 8.0F);
	public static final Vector3f TIP_PX = new Vector3f(8.0F, 30.0F, 8.0F);

	private static final float[] FP_ROTATION = {-25.0F, -15.0F, 25.0F};
	private static final float[] FP_TRANSLATION = {0.34F, 0.63F, -1.28F};
	private static final float FP_SCALE = 0.55F;
	private static final float[] TP_ROTATION = {-30.0F, -90.0F, -40.0F};
	private static final float[] TP_TRANSLATION = {0.0F, 0.81F, 1.82F};
	private static final float TP_SCALE = 0.62F;

	private BladeGeometry() {
	}

	/** Appends the item display transform to a hand pose (the pose right before the item is submitted). */
	public static Matrix4f withDisplay(Matrix4f handPose, boolean firstPerson, boolean leftHand) {
		float[] rotation = firstPerson ? FP_ROTATION : TP_ROTATION;
		float[] translation = firstPerson ? FP_TRANSLATION : TP_TRANSLATION;
		float scale = firstPerson ? FP_SCALE : TP_SCALE;
		float tx = (leftHand ? -translation[0] : translation[0]) / 16.0F;
		float ry = leftHand ? -rotation[1] : rotation[1];
		float rz = leftHand ? -rotation[2] : rotation[2];
		return new Matrix4f(handPose)
			.translate(tx, translation[1] / 16.0F, translation[2] / 16.0F)
			.rotate(new Quaternionf().rotationXYZ(rotation[0] * Mth.DEG_TO_RAD, ry * Mth.DEG_TO_RAD, rz * Mth.DEG_TO_RAD))
			.scale(scale)
			.translate(-0.5F, -0.5F, -0.5F);
	}

	public static void base(Matrix4f modelPose, Vector3f out) {
		modelPose.transformPosition(BASE_PX.x / 16.0F, BASE_PX.y / 16.0F, BASE_PX.z / 16.0F, out);
	}

	public static void tip(Matrix4f modelPose, Vector3f out) {
		modelPose.transformPosition(TIP_PX.x / 16.0F, TIP_PX.y / 16.0F, TIP_PX.z / 16.0F, out);
	}

	/** A point along the blade, 0 = root, 1 = tip. */
	public static void along(Matrix4f modelPose, float t, Vector3f out) {
		modelPose.transformPosition(
			Mth.lerp(t, BASE_PX.x, TIP_PX.x) / 16.0F,
			Mth.lerp(t, BASE_PX.y, TIP_PX.y) / 16.0F,
			Mth.lerp(t, BASE_PX.z, TIP_PX.z) / 16.0F,
			out
		);
	}
}
